CREATE TABLE IF NOT EXISTS processed_messages (
  message_id TEXT PRIMARY KEY,
  customer_phone TEXT,
  processed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE conversation_sessions ADD COLUMN IF NOT EXISTS recent_messages JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE conversation_sessions ADD COLUMN IF NOT EXISTS order_status TEXT NOT NULL DEFAULT 'draft';
ALTER TABLE conversation_sessions ADD COLUMN IF NOT EXISTS active_order_id BIGINT;
ALTER TABLE conversation_sessions ADD COLUMN IF NOT EXISTS awaiting_human BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS admin_requests (
  id BIGSERIAL PRIMARY KEY,
  customer_id BIGINT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  order_id BIGINT REFERENCES orders(id) ON DELETE SET NULL,
  request_type TEXT NOT NULL,
  question TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'denied')),
  admin_note TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  resolved_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_admin_requests_status ON admin_requests (status, created_at);

SELECT EXISTS (
    SELECT 1 FROM processed_messages WHERE message_id = $1
) AS already_processed;

SELECT restaurant_name, currency, delivery_charge, opening_hours
FROM restaurant_settings
WHERE id = 1;

UPDATE conversation_sessions
SET pending_items = (
  SELECT COALESCE(jsonb_agg(elem ORDER BY (elem->>'noted_at')::timestamptz DESC), '[]'::jsonb)
  FROM (
    SELECT elem
    FROM jsonb_array_elements(
      pending_items || jsonb_build_array(
        jsonb_build_object('item', $2::text, 'noted_at', NOW())
      )
    ) elem
    ORDER BY (elem->>'noted_at')::timestamptz DESC
    LIMIT 3
  ) t
)
WHERE customer_id = (SELECT id FROM customers WHERE whatsapp_phone = $1)
RETURNING pending_items;

INSERT INTO message_buffer (customer_phone, message_text)
VALUES ($1, $2)
RETURNING id, received_at;

WITH ins AS (
  INSERT INTO admin_requests (customer_id, order_id, request_type, question)
  VALUES ($1, $2, 'cancel_order', $3)
  RETURNING id
),
flag AS (
  UPDATE conversation_sessions SET awaiting_human = TRUE, updated_at = NOW()
  WHERE customer_id = $1
)
SELECT id AS request_id FROM ins;
